import React, { useState, useCallback, useEffect, useRef } from 'react';
import Board from './components/Board.tsx';
import GameInfo from './components/GameInfo.tsx';
import ResetButton from './components/ResetButton.tsx';
import GameModeSelector from './components/GameModeSelector.tsx';
import SettingsButton from './components/SettingsButton.tsx';
import SettingsModal from './components/SettingsModal.tsx';
import StatsButton from './components/StatsButton.tsx';
import StatsModal from './components/StatsModal.tsx';
import TipsButton from './components/TipsButton.tsx';
import Confetti from './components/Confetti.tsx';
import { t } from './utils/translations.ts';
import type { SquareValue, Player, GameMode, AIDifficulty, ThemeName, GameStats, Language } from './types.ts';

// --- Constants ---
const humanPlayer: Player = 'X';
const aiPlayer: Player = 'O';

const initialStats: GameStats = {
  totalGames: 0,
  xWins: 0,
  oWins: 0,
  draws: 0,
  xStreak: 0,
  oStreak: 0,
};

const themes: Record<ThemeName, Record<string, string>> = {
  classic: {
    '--color-background': '#0f172a',
    '--color-text-primary': '#e2e8f0',
    '--color-text-secondary': '#94a3b8',
    '--color-player-x': '#22d3ee',
    '--color-player-o': '#facc15',
    '--color-accent': '#7c3aed',
    '--color-accent-hover': '#6d28d9',
    '--color-board-bg': '#1f2937',
    '--color-square-bg': '#0f172a',
    '--color-square-hover': '#374151',
    '--color-win-bg': '#16a34a',
    '--color-gradient-from': '#22d3ee',
    '--color-gradient-to': '#8b5cf6',
  },
  forest: {
    '--color-background': '#1a2e27',
    '--color-text-primary': '#dce2d9',
    '--color-text-secondary': '#9eac9b',
    '--color-player-x': '#84cc16',
    '--color-player-o': '#f59e0b',
    '--color-accent': '#10b981',
    '--color-accent-hover': '#059669',
    '--color-board-bg': '#223c33',
    '--color-square-bg': '#1a2e27',
    '--color-square-hover': '#2f4d40',
    '--color-win-bg': '#10b981',
    '--color-gradient-from': '#84cc16',
    '--color-gradient-to': '#10b981',
  },
  neon: {
    '--color-background': '#111117',
    '--color-text-primary': '#d3d4da',
    '--color-text-secondary': '#898991',
    '--color-player-x': '#f472b6',
    '--color-player-o': '#00ffff',
    '--color-accent': '#eab308',
    '--color-accent-hover': '#ca8a04',
    '--color-board-bg': '#1b1b22',
    '--color-square-bg': '#111117',
    '--color-square-hover': '#292933',
    '--color-win-bg': '#f472b6',
    '--color-gradient-from': '#f472b6',
    '--color-gradient-to': '#00ffff',
  },
};


// --- Sound Effects Engine ---
let audioContext: AudioContext | null = null;
const getAudioContext = (): AudioContext | null => {
  if (typeof window !== 'undefined' && !audioContext) {
    audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
  }
  return audioContext;
};
// --- End Sound Effects Engine ---

interface WinnerInfo {
  winner: Player | null;
  line: number[] | null;
}

const App: React.FC = () => {
  const [board, setBoard] = useState<SquareValue[]>(Array(9).fill(null));
  const [currentPlayer, setCurrentPlayer] = useState<Player>('X');
  const [winner, setWinner] = useState<Player | 'Draw' | null>(null);
  const [winningLine, setWinningLine] = useState<number[] | null>(null);
  const [gameMode, setGameMode] = useState<GameMode | null>(null);
  const [isAiTurn, setIsAiTurn] = useState<boolean>(false);
  const [aiDifficulty, setAiDifficulty] = useState<AIDifficulty | null>(null);
  const [startingPlayer, setStartingPlayer] = useState<Player>('X');
  const [aiHasMoved, setAiHasMoved] = useState<boolean>(false);

  // Settings State
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isSoundEnabled, setIsSoundEnabled] = useState(true);
  const [volume, setVolume] = useState(0.5);
  const [theme, setTheme] = useState<ThemeName>('classic');
  const [isHapticEnabled, setIsHapticEnabled] = useState(true);
  const [language, setLanguage] = useState<Language>('en');

  // Stats State
  const [stats, setStats] = useState<GameStats>(initialStats);
  const [isStatsModalOpen, setIsStatsModalOpen] = useState(false);

  // Animation state
  const [isViewFading, setIsViewFading] = useState(false);

  // Tip state
  const [suggestedMove, setSuggestedMove] = useState<number | null>(null);

  // Splash Screen State
  const [showSplashScreen, setShowSplashScreen] = useState(true);

  // Move processing lock
  const moveInProgress = useRef(false);

  // Splash Screen Timer
  useEffect(() => {
    const timer = setTimeout(() => {
        setShowSplashScreen(false);
    }, 1000); // Display for 1 second

    return () => clearTimeout(timer);
  }, []);

  // Load theme, stats, and language from localStorage on initial load
  useEffect(() => {
    try {
      const storedTheme = localStorage.getItem('tickey-theme');
      if (storedTheme && themes[storedTheme as ThemeName]) {
        setTheme(storedTheme as ThemeName);
      }
      const storedStats = localStorage.getItem('tickey-stats');
      if (storedStats) {
        setStats(JSON.parse(storedStats));
      }
      const storedLang = localStorage.getItem('tickey-language');
      if (storedLang) {
        setLanguage(storedLang as Language);
      }
    } catch (error) {
      console.error("Failed to parse from localStorage", error);
    }
  }, []);

  // Save stats to localStorage whenever they change
  useEffect(() => {
    localStorage.setItem('tickey-stats', JSON.stringify(stats));
  }, [stats]);

  // Apply and save theme
  useEffect(() => {
    const root = document.documentElement;
    const selectedTheme = themes[theme];
    for (const [key, value] of Object.entries(selectedTheme)) {
      root.style.setProperty(key, value as string);
    }
    localStorage.setItem('tickey-theme', theme);
  }, [theme]);

  // Save language to localStorage whenever it changes
  useEffect(() => {
    localStorage.setItem('tickey-language', language);
  }, [language]);

  // After a move is processed and the board state is updated, release the move lock.
  useEffect(() => {
    moveInProgress.current = false;
  }, [board]);

  const playSound = useCallback((type: 'click' | 'win' | 'draw') => {
    if (!isSoundEnabled) return;

    const ctx = getAudioContext();
    if (!ctx) return;

    if (ctx.state === 'suspended') {
      ctx.resume();
    }

    const oscillator = ctx.createOscillator();
    const gainNode = ctx.createGain();

    oscillator.connect(gainNode);
    gainNode.connect(ctx.destination);

    const now = ctx.currentTime;
    gainNode.gain.setValueAtTime(volume * 0.2, now);

    switch (type) {
      case 'click':
        oscillator.type = 'sine';
        oscillator.frequency.setValueAtTime(600, now);
        gainNode.gain.exponentialRampToValueAtTime(0.0001, now + 0.1);
        oscillator.start(now);
        oscillator.stop(now + 0.1);
        break;
      case 'win':
        oscillator.type = 'triangle';
        oscillator.frequency.setValueAtTime(440, now);
        oscillator.frequency.linearRampToValueAtTime(880, now + 0.2);
        gainNode.gain.exponentialRampToValueAtTime(0.0001, now + 0.3);
        oscillator.start(now);
        oscillator.stop(now + 0.3);
        break;
      case 'draw':
        oscillator.type = 'square';
        oscillator.frequency.setValueAtTime(330, now);
        oscillator.frequency.linearRampToValueAtTime(220, now + 0.2);
        gainNode.gain.exponentialRampToValueAtTime(0.0001, now + 0.3);
        oscillator.start(now);
        oscillator.stop(now + 0.3);
        break;
    }
  }, [isSoundEnabled, volume]);

  const triggerHaptics = useCallback((type: 'click' | 'win' | 'draw') => {
    if (!isHapticEnabled || !window.navigator.vibrate) return;

    switch (type) {
      case 'click':
        window.navigator.vibrate(50);
        break;
      case 'win':
        window.navigator.vibrate([100, 30, 100]);
        break;
      case 'draw':
        window.navigator.vibrate([75, 50, 75]);
        break;
    }
  }, [isHapticEnabled]);

  const calculateWinner = useCallback((squares: SquareValue[]): WinnerInfo => {
    const lines = [
      [0, 1, 2], [3, 4, 5], [6, 7, 8],
      [0, 3, 6], [1, 4, 7], [2, 5, 8],
      [0, 4, 8], [2, 4, 6],
    ];
    for (let i = 0; i < lines.length; i++) {
      const [a, b, c] = lines[i];
      if (squares[a] && squares[a] === squares[b] && squares[a] === squares[c]) {
        return { winner: squares[a] as Player, line: lines[i] };
      }
    }
    return { winner: null, line: null };
  }, []);

  // Update stats when a game is won or drawn
  useEffect(() => {
    if (winner) {
      setStats(prevStats => {
        const newStats: GameStats = { ...prevStats, totalGames: prevStats.totalGames + 1 };
        if (winner === 'X') {
          newStats.xWins += 1;
          newStats.xStreak += 1;
          newStats.oStreak = 0;
        } else if (winner === 'O') {
          newStats.oWins += 1;
          newStats.oStreak += 1;
          newStats.xStreak = 0;
        } else if (winner === 'Draw') {
          newStats.draws += 1;
          newStats.xStreak = 0;
          newStats.oStreak = 0;
        }
        return newStats;
      });
    }
  }, [winner]);

  const handleSquareClick = useCallback((index: number) => {
    if (winner || board[index] || moveInProgress.current) {
      return;
    }
    moveInProgress.current = true;
    setSuggestedMove(null);

    const newBoard = [...board];
    newBoard[index] = currentPlayer;
    setBoard(newBoard);
    playSound('click');
    triggerHaptics('click');

    const { winner: newWinner, line: newLine } = calculateWinner(newBoard);
    if (newWinner) {
      setWinner(newWinner);
      setWinningLine(newLine);
      playSound('win');
      triggerHaptics('win');
    } else if (newBoard.every(square => square !== null)) {
      setWinner('Draw');
      playSound('draw');
      triggerHaptics('draw');
    } else {
      setCurrentPlayer(currentPlayer === 'X' ? 'O' : 'X');
    }
  }, [board, currentPlayer, winner, calculateWinner, playSound, triggerHaptics]);

  const quitAndResetToMenu = useCallback(() => {
    setIsViewFading(true);
    setTimeout(() => {
      setBoard(Array(9).fill(null));
      setCurrentPlayer('X');
      setWinner(null);
      setWinningLine(null);
      setIsAiTurn(false);
      setGameMode(null);
      setAiDifficulty(null);
      setStartingPlayer('X');
      setAiHasMoved(false);
      setSuggestedMove(null);
      setIsViewFading(false);
    }, 300);
  }, []);

  const restartGame = useCallback(() => {
    setIsViewFading(true);
    setTimeout(() => {
      setBoard(Array(9).fill(null));
      setCurrentPlayer(startingPlayer);
      setWinner(null);
      setWinningLine(null);
      setIsAiTurn(false);
      setStartingPlayer(prev => prev === 'X' ? 'O' : 'X');
      setAiHasMoved(false);
      setSuggestedMove(null);
      setIsViewFading(false);
    }, 300);
  }, [startingPlayer]);

  const previewTheme = (previewThemeName: ThemeName | null) => {
    const root = document.documentElement;
    const themeToApply = previewThemeName ? themes[previewThemeName] : themes[theme];
    for (const [key, value] of Object.entries(themeToApply)) {
        root.style.setProperty(key, value as string);
    }
  };

  const handleSettingsClose = () => {
    previewTheme(null); // Revert to saved theme on close
    setIsSettingsOpen(false);
  };

  const handleQuitGame = () => {
    quitAndResetToMenu();
    handleSettingsClose();
  };

  const handleResetStats = () => {
    setStats(initialStats);
  };

  const minimax = useCallback((newBoard: SquareValue[], player: Player): number => {
    const { winner: gameWinner } = calculateWinner(newBoard);
    if (gameWinner === aiPlayer) return 10;
    if (gameWinner === humanPlayer) return -10;
    if (newBoard.every(square => square !== null)) return 0;

    const emptySquares = newBoard
      .map((val, index) => (val === null ? index : null))
      .filter((val): val is number => val !== null);

    if (player === aiPlayer) {
        let bestScore = -Infinity;
        for (const i of emptySquares) {
            const tempBoard = [...newBoard];
            tempBoard[i] = aiPlayer;
            const score = minimax(tempBoard, humanPlayer);
            bestScore = Math.max(bestScore, score);
        }
        return bestScore;
    } else {
        let bestScore = Infinity;
        for (const i of emptySquares) {
            const tempBoard = [...newBoard];
            tempBoard[i] = humanPlayer;
            const score = minimax(tempBoard, aiPlayer);
            bestScore = Math.min(bestScore, score);
        }
        return bestScore;
    }
  }, [calculateWinner]);

  const handleHintClick = useCallback(() => {
    // Easy difficulty gets simple hints
    if (aiDifficulty === 'easy') {
        const emptySquares = board
            .map((val, index) => (val === null ? index : null))
            .filter((val): val is number => val !== null);

        // 1. Check if Human can win
        for (const i of emptySquares) {
            const tempBoard = [...board];
            tempBoard[i] = humanPlayer;
            if (calculateWinner(tempBoard).winner === humanPlayer) {
                setSuggestedMove(i);
                return;
            }
        }
        // 2. Check if AI can win, and block it
        for (const i of emptySquares) {
            const tempBoard = [...board];
            tempBoard[i] = aiPlayer;
            if (calculateWinner(tempBoard).winner === aiPlayer) {
                setSuggestedMove(i);
                return;
            }
        }
        // 3. Otherwise, suggest a random move
        setSuggestedMove(emptySquares[Math.floor(Math.random() * emptySquares.length)]);
        return;
    }

    // Medium and Hard difficulty hints use minimax for the optimal move
    const emptySquares = board
      .map((val, index) => (val === null ? index : null))
      .filter((val): val is number => val !== null);

    let bestScore = Infinity;
    let bestMove = -1;

    for (const i of emptySquares) {
        const tempBoard = [...board];
        tempBoard[i] = humanPlayer; // Try a move for the human
        const score = minimax(tempBoard, aiPlayer); // See what the AI would do next
        if (score < bestScore) {
            bestScore = score;
            bestMove = i;
        }
    }
    setSuggestedMove(bestMove);
}, [board, minimax, aiDifficulty, calculateWinner]);

  useEffect(() => {
    if (gameMode === 'pva' && currentPlayer === aiPlayer && !winner && aiDifficulty) {
      setIsAiTurn(true);
      if (!aiHasMoved) {
        setAiHasMoved(true);
      }

      const findAiMove = (squares: SquareValue[], difficulty: AIDifficulty): number => {
        const emptySquares = squares
          .map((val, index) => (val === null ? index : null))
          .filter((val): val is number => val !== null);

        switch (difficulty) {
          case 'easy': {
            return emptySquares[Math.floor(Math.random() * emptySquares.length)];
          }
          case 'medium': {
             // 1. Check if AI can win
            for (const i of emptySquares) {
              const tempBoard = [...squares];
              tempBoard[i] = aiPlayer;
              if (calculateWinner(tempBoard).winner === aiPlayer) return i;
            }
            // 2. Check if Human can win, and block it
            for (const i of emptySquares) {
              const tempBoard = [...squares];
              tempBoard[i] = humanPlayer;
              if (calculateWinner(tempBoard).winner === humanPlayer) return i;
            }
            // 3. Otherwise, random move
            return emptySquares[Math.floor(Math.random() * emptySquares.length)];
          }
          case 'hard': {
            if (emptySquares.length === 9) {
                const corners = [0, 2, 6, 8];
                return corners[Math.floor(Math.random() * corners.length)];
            }

            let bestScore = -Infinity;
            let bestMove = -1;

            for (const i of emptySquares) {
                const tempBoard = [...squares];
                tempBoard[i] = aiPlayer;
                const score = minimax(tempBoard, humanPlayer);
                if (score > bestScore) {
                    bestScore = score;
                    bestMove = i;
                }
            }
            return bestMove;
          }
        }
      };

      setTimeout(() => {
        const move = findAiMove(board, aiDifficulty);
        handleSquareClick(move);
        setIsAiTurn(false);
      }, 500);
    }
  }, [gameMode, currentPlayer, winner, board, handleSquareClick, calculateWinner, aiDifficulty, aiHasMoved, minimax]);

  const startGame = useCallback((mode: GameMode, difficulty?: AIDifficulty) => {
    setIsViewFading(true);
    setTimeout(() => {
      setGameMode(mode);
      setAiDifficulty(difficulty || null);
      setBoard(Array(9).fill(null));
      setCurrentPlayer(startingPlayer);
      setWinner(null);
      setWinningLine(null);
      setIsAiTurn(false);
      setAiHasMoved(false);
      setStartingPlayer(prev => prev === 'X' ? 'O' : 'X');
      setIsViewFading(false);
    }, 300);
  }, [startingPlayer]);

  if (showSplashScreen) {
    return (
      <div className="min-h-screen bg-[--color-background] text-[--color-text-primary] flex flex-col items-center justify-center p-4 font-sans animate-fade-in">
        <div className="text-center">
          <h1 className="text-8xl font-bold tracking-tighter text-transparent bg-clip-text bg-gradient-to-r from-[var(--color-gradient-from)] to-[var(--color-gradient-to)] animate-pop-in">
            Tickey!
          </h1>
          <p className="text-[--color-text-secondary] mt-4 text-xl animate-fade-in" style={{ animationDelay: '0.4s' }}>
            With ❤️ By ARITRA
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[--color-background] text-[--color-text-primary] flex flex-col items-center justify-center p-4 font-sans relative overflow-hidden animate-fade-in">
      {(winner === 'X' || winner === 'O') && <Confetti winner={winner} />}
      <div className="absolute top-4 right-4 z-10 flex items-center gap-2">
        {gameMode === 'pva' && aiHasMoved && !winner && currentPlayer === humanPlayer && (
          <TipsButton onClick={handleHintClick} />
        )}
        <StatsButton onClick={() => setIsStatsModalOpen(true)} />
        <SettingsButton onClick={() => setIsSettingsOpen(true)} />
      </div>
       <SettingsModal
        isOpen={isSettingsOpen}
        onClose={handleSettingsClose}
        isSoundEnabled={isSoundEnabled}
        onSoundToggle={() => setIsSoundEnabled(prev => !prev)}
        volume={volume}
        onVolumeChange={(e) => setVolume(parseFloat(e.target.value))}
        theme={theme}
        onThemeChange={setTheme}
        onThemePreview={previewTheme}
        isHapticEnabled={isHapticEnabled}
        onHapticToggle={() => setIsHapticEnabled(prev => !prev)}
        gameMode={gameMode}
        onQuitGame={handleQuitGame}
        language={language}
        onLanguageChange={setLanguage}
      />
      <StatsModal
        isOpen={isStatsModalOpen}
        onClose={() => setIsStatsModalOpen(false)}
        stats={stats}
        onResetStats={handleResetStats}
        language={language}
      />

      <header className="mb-8 text-center">
        <h1 className="text-6xl font-bold tracking-tighter text-transparent bg-clip-text bg-gradient-to-r from-[var(--color-gradient-from)] to-[var(--color-gradient-to)]">
          Tickey!
        </h1>
        <p className="text-[--color-text-secondary] mt-2">{t('subtitle', language)}</p>
      </header>

      <main className="flex flex-col items-center">
        {gameMode ? (
          <div className={`flex flex-col items-center ${isViewFading ? 'animate-fade-out' : 'animate-fade-in'}`}>
            <GameInfo winner={winner} currentPlayer={currentPlayer} gameMode={gameMode} isAiTurn={isAiTurn} stats={stats} language={language} />
            <Board squares={board} onSquareClick={handleSquareClick} winner={winner} isLocked={isAiTurn} winningLine={winningLine} suggestedMove={suggestedMove} isDraw={winner === 'Draw'} currentPlayer={currentPlayer} />
            <ResetButton onReset={restartGame} onQuit={quitAndResetToMenu} winner={winner} language={language} />
          </div>
        ) : (
          <div className={isViewFading ? 'animate-fade-out' : 'animate-fade-in'}>
            <GameModeSelector onSelectMode={startGame} isSoundEnabled={isSoundEnabled} onSoundToggle={() => setIsSoundEnabled(prev => !prev)} language={language} />
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useCallback, useEffect, useRef } from 'react';
import Board from './components/Board.tsx';
import GameInfo from './components/GameInfo.tsx';
import ResetButton from './components/ResetButton.tsx';
import GameModeSelector from './components/GameModeSelector.tsx';
import SettingsButton from './components/SettingsButton.tsx';
import SettingsModal from './components/SettingsModal.tsx';
import StatsButton from './components/StatsButton.tsx';
import StatsModal from './components/StatsModal.tsx';
import TipsButton from './components/TipsButton.tsx';
import Confetti from './components/Confetti.tsx';
import { t } from './utils/translations.ts';
import type { SquareValue, Player, GameMode, AIDifficulty, ThemeName, GameStats, Language } from './types.ts';

// --- Constants ---
const humanPlayer: Player = 'X';
const aiPlayer: Player = 'O';

const initialStats: GameStats = {
  totalGames: 0,
  xWins: 0,
  oWins: 0,
  draws: 0,
  xStreak: 0,
  oStreak: 0,
};

const themes: Record<ThemeName, Record<string, string>> = {
  classic: {
    '--color-background': '#0f172a',
    '--color-text-primary': '#e2e8f0',
    '--color-text-secondary': '#94a3b8',
    '--color-player-x': '#22d3ee',
    '--color-player-o': '#facc15',
    '--color-accent': '#7c3aed',
    '--color-accent-hover': '#6d28d9',
    '--color-board-bg': '#1f2937',
    '--color-square-bg': '#0f172a',
    '--color-square-hover': '#374151',
    '--color-win-bg': '#16a34a',
    '--color-gradient-from': '#22d3ee',
    '--color-gradient-to': '#8b5cf6',
  },
  forest: {
    '--color-background': '#1a2e27',
    '--color-text-primary': '#dce2d9',
    '--color-text-secondary': '#9eac9b',
    '--color-player-x': '#84cc16',
    '--color-player-o': '#f59e0b',
    '--color-accent': '#10b981',
    '--color-accent-hover': '#059669',
    '--color-board-bg': '#223c33',
    '--color-square-bg': '#1a2e27',
    '--color-square-hover': '#2f4d40',
    '--color-win-bg': '#10b981',
    '--color-gradient-from': '#84cc16',
    '--color-gradient-to': '#10b981',
  },
  neon: {
    '--color-background': '#111117',
    '--color-text-primary': '#d3d4da',
    '--color-text-secondary': '#898991',
    '--color-player-x': '#f472b6',
    '--color-player-o': '#00ffff',
    '--color-accent': '#eab308',
    '--color-accent-hover': '#ca8a04',
    '--color-board-bg': '#1b1b22',
    '--color-square-bg': '#111117',
    '--color-square-hover': '#292933',
    '--color-win-bg': '#f472b6',
    '--color-gradient-from': '#f472b6',
    '--color-gradient-to': '#00ffff',
  },
};


// --- Sound Effects Engine ---
let audioContext: AudioContext | null = null;
const getAudioContext = (): AudioContext | null => {
  if (typeof window !== 'undefined' && !audioContext) {
    audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
  }
  return audioContext;
};
// --- End Sound Effects Engine ---

interface WinnerInfo {
  winner: Player | null;
  line: number[] | null;
}

const App: React.FC = () => {
  const [board, setBoard] = useState<SquareValue[]>(Array(9).fill(null));
  const [currentPlayer, setCurrentPlayer] = useState<Player>('X');
  const [winner, setWinner] = useState<Player | 'Draw' | null>(null);
  const [winningLine, setWinningLine] = useState<number[] | null>(null);
  const [gameMode, setGameMode] = useState<GameMode | null>(null);
  const [isAiTurn, setIsAiTurn] = useState<boolean>(false);
  const [aiDifficulty, setAiDifficulty] = useState<AIDifficulty | null>(null);
  const [startingPlayer, setStartingPlayer] = useState<Player>('X');
  const [aiHasMoved, setAiHasMoved] = useState<boolean>(false);

  // Settings State
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isSoundEnabled, setIsSoundEnabled] = useState(true);
  const [volume, setVolume] = useState(0.5);
  const [theme, setTheme] = useState<ThemeName>('classic');
  const [isHapticEnabled, setIsHapticEnabled] = useState(true);
  const [language, setLanguage] = useState<Language>('en');

  // Board Customization State
  const [boardGridColor, setBoardGridColor] = useState<string>('');
  const [boardGap, setBoardGap] = useState<number>(12);

  // Stats State
  const [stats, setStats] = useState<GameStats>(initialStats);
  const [isStatsModalOpen, setIsStatsModalOpen] = useState(false);

  // Animation state
  const [isViewFading, setIsViewFading] = useState(false);

  // Tip state
  const [suggestedMove, setSuggestedMove] = useState<number | null>(null);

  // Splash Screen State
  const [showSplashScreen, setShowSplashScreen] = useState(true);

  // Move processing lock
  const moveInProgress = useRef(false);

  // Splash Screen Timer
  useEffect(() => {
    const timer = setTimeout(() => {
        setShowSplashScreen(false);
    }, 1000); // Display for 1 second

    return () => clearTimeout(timer);
  }, []);

  // Load theme, stats, language, and custom board settings from localStorage on initial load
  useEffect(() => {
    try {
      const storedTheme = localStorage.getItem('tickey-theme');
      if (storedTheme && themes[storedTheme as ThemeName]) {
        setTheme(storedTheme as ThemeName);
        // Default color for theme
        setBoardGridColor(themes[storedTheme as ThemeName]['--color-board-bg']);
      }

      const storedStats = localStorage.getItem('tickey-stats');
      if (storedStats) {
        setStats(JSON.parse(storedStats));
      }

      const storedLang = localStorage.getItem('tickey-language');
      if (storedLang) {
        setLanguage(storedLang as Language);
      }

      const storedGridColor = localStorage.getItem('tickey-board-grid-color');
      if (storedGridColor) {
        setBoardGridColor(storedGridColor);
      }

      const storedGap = localStorage.getItem('tickey-board-gap');
      if (storedGap) {
        setBoardGap(parseInt(storedGap, 10));
      }
    } catch (error) {
      console.error("Failed to parse from localStorage", error);
    }
  }, []);

  // Save stats to localStorage whenever they change
  useEffect(() => {
    localStorage.setItem('tickey-stats', JSON.stringify(stats));
  }, [stats]);

  // Apply and save theme
  useEffect(() => {
    const root = document.documentElement;
    const selectedTheme = themes[theme];
    for (const [key, value] of Object.entries(selectedTheme)) {
      root.style.setProperty(key, value as string);
    }

    // If we haven't manually overridden grid color yet, or if switching theme resets it
    // For this app, let's keep custom color unless theme is changed and we want to sync
    // Sync logic: if localStorage doesn't have a manual override, use theme's board-bg
    if (!localStorage.getItem('tickey-board-grid-color')) {
        setBoardGridColor(selectedTheme['--color-board-bg']);
    }

    localStorage.setItem('tickey-theme', theme);
  }, [theme]);

  // Apply Board Customizations
  useEffect(() => {
    const root = document.documentElement;
    if (boardGridColor) {
        root.style.setProperty('--board-grid-color', boardGridColor);
    }
    root.style.setProperty('--board-gap', `${boardGap}px`);
  }, [boardGridColor, boardGap]);

  // Save board settings
  useEffect(() => {
    if (boardGridColor) {
        localStorage.setItem('tickey-board-grid-color', boardGridColor);
    }
    localStorage.setItem('tickey-board-gap', boardGap.toString());
  }, [boardGridColor, boardGap]);

  // Save language to localStorage whenever it changes
  useEffect(() => {
    localStorage.setItem('tickey-language', language);
  }, [language]);

  // After a move is processed and the board state is updated, release the move lock.
  useEffect(() => {
    moveInProgress.current = false;
  }, [board]);

  const playSound = useCallback((type: 'click' | 'win' | 'draw') => {
    if (!isSoundEnabled) return;

    const ctx = getAudioContext();
    if (!ctx) return;

    if (ctx.state === 'suspended') {
      ctx.resume();
    }

    const oscillator = ctx.createOscillator();
    const gainNode = ctx.createGain();

    oscillator.connect(gainNode);
    gainNode.connect(ctx.destination);

    const now = ctx.currentTime;
    gainNode.gain.setValueAtTime(volume * 0.2, now);

    switch (type) {
      case 'click':
        oscillator.type = 'sine';
        oscillator.frequency.setValueAtTime(600, now);
        gainNode.gain.exponentialRampToValueAtTime(0.0001, now + 0.1);
        oscillator.start(now);
        oscillator.stop(now + 0.1);
        break;
      case 'win':
        oscillator.type = 'triangle';
        oscillator.frequency.setValueAtTime(440, now);
        oscillator.frequency.linearRampToValueAtTime(880, now + 0.2);
        gainNode.gain.exponentialRampToValueAtTime(0.0001, now + 0.3);
        oscillator.start(now);
        oscillator.stop(now + 0.3);
        break;
      case 'draw':
        oscillator.type = 'square';
        oscillator.frequency.setValueAtTime(330, now);
        oscillator.frequency.linearRampToValueAtTime(220, now + 0.2);
        gainNode.gain.exponentialRampToValueAtTime(0.0001, now + 0.3);
        oscillator.start(now);
        oscillator.stop(now + 0.3);
        break;
    }
  }, [isSoundEnabled, volume]);

  const triggerHaptics = useCallback((type: 'click' | 'win' | 'draw') => {
    if (!isHapticEnabled || !window.navigator.vibrate) return;

    switch (type) {
      case 'click':
        window.navigator.vibrate(50);
        break;
      case 'win':
        window.navigator.vibrate([100, 30, 100]);
        break;
      case 'draw':
        window.navigator.vibrate([75, 50, 75]);
        break;
    }
  }, [isHapticEnabled]);

  const calculateWinner = useCallback((squares: SquareValue[]): WinnerInfo => {
    const lines = [
      [0, 1, 2], [3, 4, 5], [6, 7, 8],
      [0, 3, 6], [1, 4, 7], [2, 5, 8],
      [0, 4, 8], [2, 4, 6],
    ];
    for (let i = 0; i < lines.length; i++) {
      const [a, b, c] = lines[i];
      if (squares[a] && squares[a] === squares[b] && squares[a] === squares[c]) {
        return { winner: squares[a] as Player, line: lines[i] };
      }
    }
    return { winner: null, line: null };
  }, []);

  // Update stats when a game is won or drawn
  useEffect(() => {
    if (winner) {
      setStats(prevStats => {
        const newStats: GameStats = { ...prevStats, totalGames: prevStats.totalGames + 1 };
        if (winner === 'X') {
          newStats.xWins += 1;
          newStats.xStreak += 1;
          newStats.oStreak = 0;
        } else if (winner === 'O') {
          newStats.oWins += 1;
          newStats.oStreak += 1;
          newStats.xStreak = 0;
        } else if (winner === 'Draw') {
          newStats.draws += 1;
          newStats.xStreak = 0;
          newStats.oStreak = 0;
        }
        return newStats;
      });
    }
  }, [winner]);

  const handleSquareClick = useCallback((index: number) => {
    if (winner || board[index] || moveInProgress.current) {
      return;
    }
    moveInProgress.current = true;
    setSuggestedMove(null);

    const newBoard = [...board];
    newBoard[index] = currentPlayer;
    setBoard(newBoard);
    playSound('click');
    triggerHaptics('click');

    const { winner: newWinner, line: newLine } = calculateWinner(newBoard);
    if (newWinner) {
      setWinner(newWinner);
      setWinningLine(newLine);
      playSound('win');
      triggerHaptics('win');
    } else if (newBoard.every(square => square !== null)) {
      setWinner('Draw');
      playSound('draw');
      triggerHaptics('draw');
    } else {
      setCurrentPlayer(currentPlayer === 'X' ? 'O' : 'X');
    }
  }, [board, currentPlayer, winner, calculateWinner, playSound, triggerHaptics]);

  const quitAndResetToMenu = useCallback(() => {
    setIsViewFading(true);
    setTimeout(() => {
      setBoard(Array(9).fill(null));
      setCurrentPlayer('X');
      setWinner(null);
      setWinningLine(null);
      setIsAiTurn(false);
      setGameMode(null);
      setAiDifficulty(null);
      setStartingPlayer('X');
      setAiHasMoved(false);
      setSuggestedMove(null);
      setIsViewFading(false);
    }, 300);
  }, []);

  const restartGame = useCallback(() => {
    setIsViewFading(true);
    setTimeout(() => {
      setBoard(Array(9).fill(null));
      setCurrentPlayer(startingPlayer);
      setWinner(null);
      setWinningLine(null);
      setIsAiTurn(false);
      setStartingPlayer(prev => prev === 'X' ? 'O' : 'X');
      setAiHasMoved(false);
      setSuggestedMove(null);
      setIsViewFading(false);
    }, 300);
  }, [startingPlayer]);

  const previewTheme = (previewThemeName: ThemeName | null) => {
    const root = document.documentElement;
    const themeToApply = previewThemeName ? themes[previewThemeName] : themes[theme];
    for (const [key, value] of Object.entries(themeToApply)) {
        root.style.setProperty(key, value as string);
    }
  };

  const handleSettingsClose = () => {
    previewTheme(null); // Revert to saved theme on close
    setIsSettingsOpen(false);
  };

  const handleQuitGame = () => {
    quitAndResetToMenu();
    handleSettingsClose();
  };

  const handleResetStats = () => {
    setStats(initialStats);
  };

  const minimax = useCallback((newBoard: SquareValue[], player: Player): number => {
    const { winner: gameWinner } = calculateWinner(newBoard);
    if (gameWinner === aiPlayer) return 10;
    if (gameWinner === humanPlayer) return -10;
    if (newBoard.every(square => square !== null)) return 0;

    const emptySquares = newBoard
      .map((val, index) => (val === null ? index : null))
      .filter((val): val is number => val !== null);

    if (player === aiPlayer) {
        let bestScore = -Infinity;
        for (const i of emptySquares) {
            const tempBoard = [...newBoard];
            tempBoard[i] = aiPlayer;
            const score = minimax(tempBoard, humanPlayer);
            bestScore = Math.max(bestScore, score);
        }
        return bestScore;
    } else {
        let bestScore = Infinity;
        for (const i of emptySquares) {
            const tempBoard = [...newBoard];
            tempBoard[i] = humanPlayer;
            const score = minimax(tempBoard, aiPlayer);
            bestScore = Math.min(bestScore, score);
        }
        return bestScore;
    }
  }, [calculateWinner]);

  const handleHintClick = useCallback(() => {
    // Easy difficulty gets simple hints
    if (aiDifficulty === 'easy') {
        const emptySquares = board
            .map((val, index) => (val === null ? index : null))
            .filter((val): val is number => val !== null);

        // 1. Check if Human can win
        for (const i of emptySquares) {
            const tempBoard = [...board];
            tempBoard[i] = humanPlayer;
            if (calculateWinner(tempBoard).winner === humanPlayer) {
                setSuggestedMove(i);
                return;
            }
        }
        // 2. Check if AI can win, and block it
        for (const i of emptySquares) {
            const tempBoard = [...board];
            tempBoard[i] = aiPlayer;
            if (calculateWinner(tempBoard).winner === aiPlayer) {
                setSuggestedMove(i);
                return;
            }
        }
        // 3. Otherwise, suggest a random move
        setSuggestedMove(emptySquares[Math.floor(Math.random() * emptySquares.length)]);
        return;
    }

    // Medium and Hard difficulty hints use minimax for the optimal move
    const emptySquares = board
      .map((val, index) => (val === null ? index : null))
      .filter((val): val is number => val !== null);

    let bestScore = Infinity;
    let bestMove = -1;

    for (const i of emptySquares) {
        const tempBoard = [...board];
        tempBoard[i] = humanPlayer; // Try a move for the human
        const score = minimax(tempBoard, aiPlayer); // See what the AI would do next
        if (score < bestScore) {
            bestScore = score;
            bestMove = i;
        }
    }
    setSuggestedMove(bestMove);
}, [board, minimax, aiDifficulty, calculateWinner]);

  useEffect(() => {
    if (gameMode === 'pva' && currentPlayer === aiPlayer && !winner && aiDifficulty) {
      setIsAiTurn(true);
      if (!aiHasMoved) {
        setAiHasMoved(true);
      }

      const findAiMove = (squares: SquareValue[], difficulty: AIDifficulty): number => {
        const emptySquares = squares
          .map((val, index) => (val === null ? index : null))
          .filter((val): val is number => val !== null);

        switch (difficulty) {
          case 'easy': {
            return emptySquares[Math.floor(Math.random() * emptySquares.length)];
          }
          case 'medium': {
             // 1. Check if AI can win
            for (const i of emptySquares) {
              const tempBoard = [...squares];
              tempBoard[i] = aiPlayer;
              if (calculateWinner(tempBoard).winner === aiPlayer) return i;
            }
            // 2. Check if Human can win, and block it
            for (const i of emptySquares) {
              const tempBoard = [...squares];
              tempBoard[i] = humanPlayer;
              if (calculateWinner(tempBoard).winner === humanPlayer) return i;
            }
            // 3. Otherwise, random move
            return emptySquares[Math.floor(Math.random() * emptySquares.length)];
          }
          case 'hard': {
            if (emptySquares.length === 9) {
                const corners = [0, 2, 6, 8];
                return corners[Math.floor(Math.random() * corners.length)];
            }

            let bestScore = -Infinity;
            let bestMove = -1;

            for (const i of emptySquares) {
                const tempBoard = [...squares];
                tempBoard[i] = aiPlayer;
                const score = minimax(tempBoard, humanPlayer);
                if (score > bestScore) {
                    bestScore = score;
                    bestMove = i;
                }
            }
            return bestMove;
          }
        }
      };

      setTimeout(() => {
        const move = findAiMove(board, aiDifficulty);
        handleSquareClick(move);
        setIsAiTurn(false);
      }, 500);
    }
  }, [gameMode, currentPlayer, winner, board, handleSquareClick, calculateWinner, aiDifficulty, aiHasMoved, minimax]);

  const startGame = useCallback((mode: GameMode, difficulty?: AIDifficulty) => {
    setIsViewFading(true);
    setTimeout(() => {
      setGameMode(mode);
      setAiDifficulty(difficulty || null);
      setBoard(Array(9).fill(null));
      setCurrentPlayer(startingPlayer);
      setWinner(null);
      setWinningLine(null);
      setIsAiTurn(false);
      setAiHasMoved(false);
      setStartingPlayer(prev => prev === 'X' ? 'O' : 'X');
      setIsViewFading(false);
    }, 300);
  }, [startingPlayer]);

  if (showSplashScreen) {
    return (
      <div className="min-h-screen bg-[--color-background] text-[--color-text-primary] flex flex-col items-center justify-center p-4 font-sans animate-fade-in">
        <div className="text-center">
          <h1 className="text-8xl font-bold tracking-tighter text-transparent bg-clip-text bg-gradient-to-r from-[var(--color-gradient-from)] to-[var(--color-gradient-to)] animate-pop-in">
            Tickey!
          </h1>
          <p className="text-[--color-text-secondary] mt-4 text-xl animate-fade-in" style={{ animationDelay: '0.4s' }}>
            With ❤️ By ARITRA
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[--color-background] text-[--color-text-primary] flex flex-col items-center justify-center p-4 font-sans relative overflow-hidden animate-fade-in">
      {(winner === 'X' || winner === 'O') && <Confetti winner={winner} />}
      <div className="absolute top-4 right-4 z-10 flex items-center gap-2">
        {gameMode === 'pva' && aiHasMoved && !winner && currentPlayer === humanPlayer && (
          <TipsButton onClick={handleHintClick} />
        )}
        <StatsButton onClick={() => setIsStatsModalOpen(true)} />
        <SettingsButton onClick={() => setIsSettingsOpen(true)} />
      </div>
       <SettingsModal
        isOpen={isSettingsOpen}
        onClose={handleSettingsClose}
        isSoundEnabled={isSoundEnabled}
        onSoundToggle={() => setIsSoundEnabled(prev => !prev)}
        volume={volume}
        onVolumeChange={(e) => setVolume(parseFloat(e.target.value))}
        theme={theme}
        onThemeChange={setTheme}
        onThemePreview={previewTheme}
        isHapticEnabled={isHapticEnabled}
        onHapticToggle={() => setIsHapticEnabled(prev => !prev)}
        gameMode={gameMode}
        onQuitGame={handleQuitGame}
        language={language}
        onLanguageChange={setLanguage}
        boardGridColor={boardGridColor}
        onBoardGridColorChange={setBoardGridColor}
        boardGap={boardGap}
        onBoardGapChange={setBoardGap}
      />
      <StatsModal
        isOpen={isStatsModalOpen}
        onClose={() => setIsStatsModalOpen(false)}
        stats={stats}
        onResetStats={handleResetStats}
        language={language}
      />

      <header className="mb-8 text-center">
        <h1 className="text-6xl font-bold tracking-tighter text-transparent bg-clip-text bg-gradient-to-r from-[var(--color-gradient-from)] to-[var(--color-gradient-to)]">
          Tickey!
        </h1>
        <p className="text-[--color-text-secondary] mt-2">{t('subtitle', language)}</p>
      </header>

      <main className="flex flex-col items-center">
        {gameMode ? (
          <div className={`flex flex-col items-center ${isViewFading ? 'animate-fade-out' : 'animate-fade-in'}`}>
            <GameInfo winner={winner} currentPlayer={currentPlayer} gameMode={gameMode} isAiTurn={isAiTurn} stats={stats} language={language} />
            <Board squares={board} onSquareClick={handleSquareClick} winner={winner} isLocked={isAiTurn} winningLine={winningLine} suggestedMove={suggestedMove} isDraw={winner === 'Draw'} currentPlayer={currentPlayer} />
            <ResetButton onReset={restartGame} onQuit={quitAndResetToMenu} winner={winner} language={language} />
          </div>
        ) : (
          <div className={isViewFading ? 'animate-fade-out' : 'animate-fade-in'}>
            <GameModeSelector onSelectMode={startGame} isSoundEnabled={isSoundEnabled} onSoundToggle={() => setIsSoundEnabled(prev => !prev)} language={language} />
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import React from 'react';
import Square from './Square.tsx';
import type { SquareValue, Player } from '../types.ts';

interface BoardProps {
  squares: SquareValue[];
  onSquareClick: (index: number) => void;
  winner: Player | 'Draw' | null;
  isLocked?: boolean;
  winningLine: number[] | null;
  suggestedMove?: number | null;
  isDraw?: boolean;
  currentPlayer: Player;
}

const Board: React.FC<BoardProps> = ({ squares, onSquareClick, winner, isLocked, winningLine, suggestedMove, isDraw, currentPlayer }) => {
  return (
    <div 
      className={`grid grid-cols-3 p-3 rounded-lg shadow-2xl transition-opacity duration-500 ${winner ? 'opacity-60' : 'opacity-100'} ${isLocked ? 'cursor-wait' : ''}`}
      style={{ 
        gap: 'var(--board-gap)', 
        backgroundColor: 'var(--board-grid-color)' 
      }}
    >
      {squares.map((value, index) => (
        <Square
          key={index}
          value={value}
          onClick={() => onSquareClick(index)}
          isLocked={isLocked}
          isWinning={winningLine?.includes(index)}
          isSuggested={index === suggestedMove}
          isDraw={isDraw}
          currentPlayer={currentPlayer}
        />
      ))}
    </div>
  );
};

export default Board;

import React, { useState, useEffect } from 'react';
import { t, languages } from '../utils/translations.ts';
import type { ThemeName, GameMode, Language } from '../types.ts';

interface SettingsModalProps {
  isOpen: boolean;
  onClose: () => void;
  isSoundEnabled: boolean;
  onSoundToggle: () => void;
  volume: number;
  onVolumeChange: (event: React.ChangeEvent<HTMLInputElement>) => void;
  theme: ThemeName;
  onThemeChange: (theme: ThemeName) => void;
  onThemePreview: (theme: ThemeName | null) => void;
  isHapticEnabled: boolean;
  onHapticToggle: () => void;
  gameMode: GameMode | null;
  onQuitGame: () => void;
  language: Language;
  onLanguageChange: (lang: Language) => void;
  boardGridColor: string;
  onBoardGridColorChange: (color: string) => void;
  boardGap: number;
  onBoardGapChange: (gap: number) => void;
}

const THEME_NAMES: ThemeName[] = ['classic', 'forest', 'neon'];

const isHapticSupported = typeof window !== 'undefined' && 'vibrate' in window.navigator;

const FullScreenLanguageSelector: React.FC<{
  currentLanguage: Language;
  onSelect: (lang: Language) => void;
  onClose: () => void;
}> = ({ currentLanguage, onSelect, onClose }) => {
  return (
    <div className="lang-menu-fullscreen" role="dialog" aria-modal="true" aria-labelledby="lang-menu-title">
      <button onClick={onClose} className="lang-menu-close-button" aria-label="Close language selection">
        <svg xmlns="http://www.w3.org/2000/svg" className="h-7 w-7" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
        </svg>
      </button>
      <div className="flex flex-col items-center">
        <h2 id="lang-menu-title" className="text-3xl font-bold text-center text-transparent bg-clip-text bg-gradient-to-r from-[var(--color-gradient-from)] to-[var(--color-gradient-to)]">
          {t('language', currentLanguage)}
        </h2>
        <div className="lang-menu-grid">
          {(Object.keys(languages) as Language[]).map(langKey => (
            <button
              key={langKey}
              onClick={() => onSelect(langKey)}
              className={`lang-menu-button ${currentLanguage === langKey ? 'lang-menu-button--active' : ''}`}
            >
              {languages[langKey]}
            </button>
          ))}
        </div>
      </div>
    </div>
  );
};

const SettingsModal: React.FC<SettingsModalProps> = ({
  isOpen,
  onClose,
  isSoundEnabled,
  onSoundToggle,
  volume,
  onVolumeChange,
  theme,
  onThemeChange,
  onThemePreview,
  isHapticEnabled,
  onHapticToggle,
  gameMode,
  onQuitGame,
  language,
  onLanguageChange,
  boardGridColor,
  onBoardGridColorChange,
  boardGap,
  onBoardGapChange,
}) => {
  const [showQuitConfirmation, setShowQuitConfirmation] = useState(false);
  const [isLanguageSelectorOpen, setIsLanguageSelectorOpen] = useState(false);

  // Reset confirmation state when modal is opened
  useEffect(() => {
    if (isOpen) {
      setShowQuitConfirmation(false);
    }
  }, [isOpen]);

  if (!isOpen) return null;

  const handleLanguageSelect = (lang: Language) => {
    onLanguageChange(lang);
    setIsLanguageSelectorOpen(false);
  };

  return (
    <div 
      className="fixed inset-0 bg-black bg-opacity-70 flex items-center justify-center z-50 animate-fade-in"
      style={{ animationDuration: '0.2s' }}
      onClick={onClose}
      role="dialog"
      aria-modal="true"
      aria-labelledby="settings-title"
    >
      <div 
        className="bg-[--color-board-bg] p-8 rounded-lg shadow-2xl w-full max-w-sm text-white relative animate-pop-in max-h-[90vh] overflow-y-auto"
        style={{ animationDuration: '0.3s' }}
        onClick={(e) => e.stopPropagation()} // Prevent closing when clicking inside modal
      >
        {isLanguageSelectorOpen && (
          <FullScreenLanguageSelector
            currentLanguage={language}
            onSelect={handleLanguageSelect}
            onClose={() => setIsLanguageSelectorOpen(false)}
          />
        )}

        {showQuitConfirmation ? (
          <div className="text-center animate-fade-in">
            <h3 id="settings-title" className="text-xl font-semibold text-[--color-text-primary] mb-6">
              {t('quitConfirmation', language)}
            </h3>
            <div className="flex justify-center gap-4">
              <button
                onClick={onQuitGame}
                className="w-28 py-2 px-4 rounded-lg bg-red-600 text-white font-semibold transition-colors hover:bg-red-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-offset-[--color-board-bg] focus:ring-red-500"
                aria-label="Confirm quit game"
              >
                {t('yes', language)}
              </button>
              <button
                onClick={() => setShowQuitConfirmation(false)}
                className="w-28 py-2 px-4 rounded-lg bg-slate-600 text-white font-semibold transition-colors hover:bg-slate-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-offset-[--color-board-bg] focus:ring-slate-500"
                aria-label="Cancel quit game"
              >
                {t('no', language)}
              </button>
            </div>
          </div>
        ) : (
          <>
            <h2 id="settings-title" className="text-3xl font-bold mb-6 text-center text-transparent bg-clip-text bg-gradient-to-r from-[var(--color-gradient-from)] to-[var(--color-gradient-to)]">{t('settingsTitle', language)}</h2>

            {/* Sound Toggle */}
            <div className="flex items-center justify-between mb-6">
              <label htmlFor="sound-toggle" className="text-lg font-medium text-[--color-text-primary]">{t('soundEffects', language)}</label>
              <button
                id="sound-toggle"
                onClick={onSoundToggle}
                className={`relative inline-flex items-center h-6 rounded-full w-11 transition-colors focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-offset-[--color-board-bg] focus:ring-[--color-accent] ${isSoundEnabled ? 'bg-[--color-accent]' : 'bg-slate-600'}`}
                role="switch"
                aria-checked={isSoundEnabled}
              >
                <span className={`inline-block w-4 h-4 transform bg-white rounded-full transition-transform ${isSoundEnabled ? 'translate-x-6' : 'translate-x-1'}`} />
              </button>
            </div>

            {/* Haptic Feedback Toggle */}
            {isHapticSupported && (
              <div className="flex items-center justify-between mb-6">
                <label htmlFor="haptic-toggle" className="text-lg font-medium text-[--color-text-primary]">{t('hapticFeedback', language)}</label>
                <button
                  id="haptic-toggle"
                  onClick={onHapticToggle}
                  className={`relative inline-flex items-center h-6 rounded-full w-11 transition-colors focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-offset-[--color-board-bg] focus:ring-[--color-accent] ${isHapticEnabled ? 'bg-[--color-accent]' : 'bg-slate-600'}`}
                  role="switch"
                  aria-checked={isHapticEnabled}
                >
                  <span className={`inline-block w-4 h-4 transform bg-white rounded-full transition-transform ${isHapticEnabled ? 'translate-x-6' : 'translate-x-1'}`} />
                </button>
              </div>
            )}

            {/* Volume Slider */}
            <div className="flex flex-col mb-6">
              <label htmlFor="volume-slider" className="text-lg font-medium text-[--color-text-primary] mb-3">{t('volume', language)}</label>
              <input
                id="volume-slider"
                type="range"
                min="0"
                max="1"
                step="0.05"
                value={volume}
                onChange={onVolumeChange}
                className="w-full h-2 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-[--color-accent]"
                disabled={!isSoundEnabled}
                aria-label="Adjust volume"
              />
            </div>

            {/* Language Selector Button */}
            <div className="mb-6">
              <label id="lang-label" className="text-lg font-medium text-[--color-text-primary] mb-3 block">{t('language', language)}</label>
              <div className="relative">
                <button
                  onClick={() => setIsLanguageSelectorOpen(true)}
                  className="w-full bg-[--color-square-hover] text-[--color-text-primary] py-2 px-3 rounded-lg flex justify-between items-center focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-offset-[--color-board-bg] focus:ring-[--color-accent]"
                  aria-haspopup="dialog"
                  aria-controls="lang-menu-fullscreen"
                >
                  <span>{languages[language]}</span>
                  <svg className="fill-current h-4 w-4" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20"><path d="M9.293 12.95l.707.707L15.657 8l-1.414-1.414L10 10.828 5.757 6.586 4.343 8z"/></svg>
                </button>
              </div>
            </div>

            {/* Theme Selector */}
            <div className="mt-8 mb-8">
              <h3 className="text-lg font-medium text-[--color-text-primary] mb-3">{t('theme', language)}</h3>
              <div className="grid grid-cols-3 gap-3">
                {THEME_NAMES.map((themeName) => (
                  <button
                    key={themeName}
                    onClick={() => onThemeChange(themeName)}
                    onMouseEnter={() => onThemePreview(themeName)}
                    onMouseLeave={() => onThemePreview(null)}
                    className={`py-2 px-4 rounded-lg capitalize transition-all focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-offset-[--color-board-bg] focus:ring-[--color-accent] ${
                      theme === themeName
                        ? 'bg-[--color-accent] text-white font-semibold ring-2 ring-[--color-accent]'
                        : 'bg-[--color-square-hover] text-[--color-text-secondary] hover:bg-[--color-accent] hover:text-white'
                    }`}
                  >
                    {themeName}
                  </button>
                ))}
              </div>
            </div>

            {/* Board Customization */}
            <div className="mt-8 pt-6 border-t border-slate-700">
              <h3 className="text-lg font-bold text-transparent bg-clip-text bg-gradient-to-r from-[var(--color-gradient-from)] to-[var(--color-gradient-to)] mb-4">{t('boardCustomization', language)}</h3>

              <div className="flex items-center justify-between mb-6">
                <label htmlFor="grid-color" className="text-md font-medium text-[--color-text-primary]">{t('gridColor', language)}</label>
                <div className="flex items-center gap-2">
                    <input 
                      id="grid-color"
                      type="color" 
                      value={boardGridColor} 
                      onChange={(e) => onBoardGridColorChange(e.target.value)}
                      className="w-10 h-10 border-none rounded cursor-pointer bg-transparent"
                    />
                </div>
              </div>

              <div className="flex flex-col mb-4">
                <div className="flex justify-between items-center mb-2">
                    <label htmlFor="square-gap" className="text-md font-medium text-[--color-text-primary]">{t('squareGap', language)}</label>
                    <span className="text-xs text-[--color-text-secondary]">{boardGap}px</span>
                </div>
                <input
                  id="square-gap"
                  type="range"
                  min="0"
                  max="24"
                  step="2"
                  value={boardGap}
                  onChange={(e) => onBoardGapChange(parseInt(e.target.value, 10))}
                  className="w-full h-2 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-[--color-accent]"
                />
              </div>
            </div>

            {/* Quit Game Button */}
            {gameMode && (
              <div className="mt-8 pt-6 border-t border-slate-700">
                <button
                  onClick={() => setShowQuitConfirmation(true)}
                  className="w-full py-3 px-4 rounded-lg bg-red-600 text-white font-semibold transition-colors hover:bg-red-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-offset-[--color-board-bg] focus:ring-red-500"
                >
                  {t('quitGame', language)}
                </button>
              </div>
            )}


            {/* Close Button */}
            <button 
              onClick={onClose}
              className="absolute top-3 right-3 p-1 rounded-full text-[--color-text-secondary] hover:bg-[--color-square-hover] hover:text-[--color-text-primary] transition-colors"
              aria-label="Close settings"
            >
               <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
              </svg>
            </button>
          </>
        )}
      </div>
    </div>
  );
};

export default SettingsModal;

import React, { useState, useCallback, useEffect, useRef } from 'react';
import Board from './components/Board.tsx';
import GameInfo from './components/GameInfo.tsx';
import ResetButton from './components/ResetButton.tsx';
import GameModeSelector from './components/GameModeSelector.tsx';
import SettingsButton from './components/SettingsButton.tsx';
import SettingsModal from './components/SettingsModal.tsx';
import StatsButton from './components/StatsButton.tsx';
import StatsModal from './components/StatsModal.tsx';
import TipsButton from './components/TipsButton.tsx';
import Confetti from './components/Confetti.tsx';
import { t } from './utils/translations.ts';
import type { SquareValue, Player, GameMode, AIDifficulty, ThemeName, GameStats, Language } from './types.ts';

// --- Constants ---
const humanPlayer: Player = 'X';
const aiPlayer: Player = 'O';

const initialStats: GameStats = {
  totalGames: 0,
  xWins: 0,
  oWins: 0,
  draws: 0,
  xStreak: 0,
  oStreak: 0,
};

const themes: Record<ThemeName, Record<string, string>> = {
  classic: {
    '--color-background': '#0f172a',
    '--color-text-primary': '#e2e8f0',
    '--color-text-secondary': '#94a3b8',
    '--color-player-x': '#22d3ee',
    '--color-player-o': '#facc15',
    '--color-accent': '#7c3aed',
    '--color-accent-hover': '#6d28d9',
    '--color-board-bg': '#1f2937',
    '--color-square-bg': '#0f172a',
    '--color-square-hover': '#374151',
    '--color-win-bg': '#16a34a',
    '--color-gradient-from': '#22d3ee',
    '--color-gradient-to': '#8b5cf6',
  },
  forest: {
    '--color-background': '#1a2e27',
    '--color-text-primary': '#dce2d9',
    '--color-text-secondary': '#9eac9b',
    '--color-player-x': '#84cc16',
    '--color-player-o': '#f59e0b',
    '--color-accent': '#10b981',
    '--color-accent-hover': '#059669',
    '--color-board-bg': '#223c33',
    '--color-square-bg': '#1a2e27',
    '--color-square-hover': '#2f4d40',
    '--color-win-bg': '#10b981',
    '--color-gradient-from': '#84cc16',
    '--color-gradient-to': '#10b981',
  },
  neon: {
    '--color-background': '#111117',
    '--color-text-primary': '#d3d4da',
    '--color-text-secondary': '#898991',
    '--color-player-x': '#f472b6',
    '--color-player-o': '#00ffff',
    '--color-accent': '#eab308',
    '--color-accent-hover': '#ca8a04',
    '--color-board-bg': '#1b1b22',
    '--color-square-bg': '#111117',
    '--color-square-hover': '#292933',
    '--color-win-bg': '#f472b6',
    '--color-gradient-from': '#f472b6',
    '--color-gradient-to': '#00ffff',
  },
};


// --- Sound Effects Engine ---
let audioContext: AudioContext | null = null;
const getAudioContext = (): AudioContext | null => {
  if (typeof window !== 'undefined' && !audioContext) {
    audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
  }
  return audioContext;
};
// --- End Sound Effects Engine ---

interface WinnerInfo {
  winner: Player | null;
  line: number[] | null;
}

const App: React.FC = () => {
  const [board, setBoard] = useState<SquareValue[]>(Array(9).fill(null));
  const [currentPlayer, setCurrentPlayer] = useState<Player>('X');
  const [winner, setWinner] = useState<Player | 'Draw' | null>(null);
  const [winningLine, setWinningLine] = useState<number[] | null>(null);
  const [gameMode, setGameMode] = useState<GameMode | null>(null);
  const [isAiTurn, setIsAiTurn] = useState<boolean>(false);
  const [aiDifficulty, setAiDifficulty] = useState<AIDifficulty | null>(null);
  const [startingPlayer, setStartingPlayer] = useState<Player>('X');
  const [aiHasMoved, setAiHasMoved] = useState<boolean>(false);

  // Settings State
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isSoundEnabled, setIsSoundEnabled] = useState(true);
  const [volume, setVolume] = useState(0.5);
  const [theme, setTheme] = useState<ThemeName>('classic');
  const [isHapticEnabled, setIsHapticEnabled] = useState(true);
  const [language, setLanguage] = useState<Language>('en');

  // Board Customization State
  const [boardGridColor, setBoardGridColor] = useState<string>('');
  const [boardGap, setBoardGap] = useState<number>(12);

  // Stats State
  const [stats, setStats] = useState<GameStats>(initialStats);
  const [isStatsModalOpen, setIsStatsModalOpen] = useState(false);

  // Animation state
  const [isViewFading, setIsViewFading] = useState(false);

  // Tip state
  const [suggestedMove, setSuggestedMove] = useState<number | null>(null);

  // Splash Screen State
  const [showSplashScreen, setShowSplashScreen] = useState(true);

  // Move processing lock
  const moveInProgress = useRef(false);

  // Splash Screen Timer
  useEffect(() => {
    const timer = setTimeout(() => {
        setShowSplashScreen(false);
    }, 1000); // Display for 1 second

    return () => clearTimeout(timer);
  }, []);

  // Load theme, stats, language, and custom board settings from localStorage on initial load
  useEffect(() => {
    try {
      const storedTheme = localStorage.getItem('tickey-theme');
      if (storedTheme && themes[storedTheme as ThemeName]) {
        setTheme(storedTheme as ThemeName);
        // Default color for theme
        setBoardGridColor(themes[storedTheme as ThemeName]['--color-board-bg']);
      }

      const storedStats = localStorage.getItem('tickey-stats');
      if (storedStats) {
        setStats(JSON.parse(storedStats));
      }

      const storedLang = localStorage.getItem('tickey-language');
      if (storedLang) {
        setLanguage(storedLang as Language);
      }

      const storedGridColor = localStorage.getItem('tickey-board-grid-color');
      if (storedGridColor) {
        setBoardGridColor(storedGridColor);
      }

      const storedGap = localStorage.getItem('tickey-board-gap');
      if (storedGap) {
        setBoardGap(parseInt(storedGap, 10));
      }
    } catch (error) {
      console.error("Failed to parse from localStorage", error);
    }
  }, []);

  // Save stats to localStorage whenever they change
  useEffect(() => {
    localStorage.setItem('tickey-stats', JSON.stringify(stats));
  }, [stats]);

  // Apply and save theme
  useEffect(() => {
    const root = document.documentElement;
    const selectedTheme = themes[theme];
    for (const [key, value] of Object.entries(selectedTheme)) {
      root.style.setProperty(key, value as string);
    }

    // If we haven't manually overridden grid color yet, or if switching theme resets it
    if (!localStorage.getItem('tickey-board-grid-color')) {
        setBoardGridColor(selectedTheme['--color-board-bg']);
    }

    localStorage.setItem('tickey-theme', theme);
  }, [theme]);

  // Apply Board Customizations
  useEffect(() => {
    const root = document.documentElement;
    if (boardGridColor) {
        root.style.setProperty('--board-grid-color', boardGridColor);
    }
    root.style.setProperty('--board-gap', `${boardGap}px`);
  }, [boardGridColor, boardGap]);

  // Save board settings
  useEffect(() => {
    if (boardGridColor) {
        localStorage.setItem('tickey-board-grid-color', boardGridColor);
    }
    localStorage.setItem('tickey-board-gap', boardGap.toString());
  }, [boardGridColor, boardGap]);

  // Save language to localStorage whenever it changes
  useEffect(() => {
    localStorage.setItem('tickey-language', language);
  }, [language]);

  // After a move is processed and the board state is updated, release the move lock.
  useEffect(() => {
    moveInProgress.current = false;
  }, [board]);

  const playSound = useCallback((type: 'click' | 'win' | 'draw') => {
    if (!isSoundEnabled) return;

    const ctx = getAudioContext();
    if (!ctx) return;

    if (ctx.state === 'suspended') {
      ctx.resume();
    }

    const oscillator = ctx.createOscillator();
    const gainNode = ctx.createGain();

    oscillator.connect(gainNode);
    gainNode.connect(ctx.destination);

    const now = ctx.currentTime;
    gainNode.gain.setValueAtTime(volume * 0.2, now);

    switch (type) {
      case 'click':
        oscillator.type = 'sine';
        oscillator.frequency.setValueAtTime(600, now);
        gainNode.gain.exponentialRampToValueAtTime(0.0001, now + 0.1);
        oscillator.start(now);
        oscillator.stop(now + 0.1);
        break;
      case 'win':
        oscillator.type = 'triangle';
        oscillator.frequency.setValueAtTime(440, now);
        oscillator.frequency.linearRampToValueAtTime(880, now + 0.2);
        gainNode.gain.exponentialRampToValueAtTime(0.0001, now + 0.3);
        oscillator.start(now);
        oscillator.stop(now + 0.3);
        break;
      case 'draw':
        oscillator.type = 'square';
        oscillator.frequency.setValueAtTime(330, now);
        oscillator.frequency.linearRampToValueAtTime(220, now + 0.2);
        gainNode.gain.exponentialRampToValueAtTime(0.0001, now + 0.3);
        oscillator.start(now);
        oscillator.stop(now + 0.3);
        break;
    }
  }, [isSoundEnabled, volume]);

  const triggerHaptics = useCallback((type: 'click' | 'win' | 'draw') => {
    if (!isHapticEnabled || !window.navigator.vibrate) return;

    switch (type) {
      case 'click':
        window.navigator.vibrate(50);
        break;
      case 'win':
        window.navigator.vibrate([100, 30, 100]);
        break;
      case 'draw':
        window.navigator.vibrate([75, 50, 75]);
        break;
    }
  }, [isHapticEnabled]);

  const calculateWinner = useCallback((squares: SquareValue[]): WinnerInfo => {
    const lines = [
      [0, 1, 2], [3, 4, 5], [6, 7, 8],
      [0, 3, 6], [1, 4, 7], [2, 5, 8],
      [0, 4, 8], [2, 4, 6],
    ];
    for (let i = 0; i < lines.length; i++) {
      const [a, b, c] = lines[i];
      if (squares[a] && squares[a] === squares[b] && squares[a] === squares[c]) {
        return { winner: squares[a] as Player, line: lines[i] };
      }
    }
    return { winner: null, line: null };
  }, []);

  // Update stats when a game is won or drawn
  useEffect(() => {
    if (winner) {
      setStats(prevStats => {
        const newStats: GameStats = { ...prevStats, totalGames: prevStats.totalGames + 1 };
        if (winner === 'X') {
          newStats.xWins += 1;
          newStats.xStreak += 1;
          newStats.oStreak = 0;
        } else if (winner === 'O') {
          newStats.oWins += 1;
          newStats.oStreak += 1;
          newStats.xStreak = 0;
        } else if (winner === 'Draw') {
          newStats.draws += 1;
          newStats.xStreak = 0;
          newStats.oStreak = 0;
        }
        return newStats;
      });
    }
  }, [winner]);

  const handleSquareClick = useCallback((index: number) => {
    if (winner || board[index] || moveInProgress.current) {
      return;
    }
    moveInProgress.current = true;
    setSuggestedMove(null);

    const newBoard = [...board];
    newBoard[index] = currentPlayer;
    setBoard(newBoard);
    playSound('click');
    triggerHaptics('click');

    const { winner: newWinner, line: newLine } = calculateWinner(newBoard);
    if (newWinner) {
      setWinner(newWinner);
      setWinningLine(newLine);
      playSound('win');
      triggerHaptics('win');
    } else if (newBoard.every(square => square !== null)) {
      setWinner('Draw');
      playSound('draw');
      triggerHaptics('draw');
    } else {
      setCurrentPlayer(currentPlayer === 'X' ? 'O' : 'X');
    }
  }, [board, currentPlayer, winner, calculateWinner, playSound, triggerHaptics]);

  const quitAndResetToMenu = useCallback(() => {
    setIsViewFading(true);
    setTimeout(() => {
      setBoard(Array(9).fill(null));
      setCurrentPlayer('X');
      setWinner(null);
      setWinningLine(null);
      setIsAiTurn(false);
      setGameMode(null);
      setAiDifficulty(null);
      setStartingPlayer('X');
      setAiHasMoved(false);
      setSuggestedMove(null);
      setIsViewFading(false);
    }, 300);
  }, []);

  const restartGame = useCallback(() => {
    setIsViewFading(true);
    setTimeout(() => {
      setBoard(Array(9).fill(null));
      setCurrentPlayer(startingPlayer);
      setWinner(null);
      setWinningLine(null);
      setIsAiTurn(false);
      setStartingPlayer(prev => prev === 'X' ? 'O' : 'X');
      setAiHasMoved(false);
      setSuggestedMove(null);
      setIsViewFading(false);
    }, 300);
  }, [startingPlayer]);

  const previewTheme = (previewThemeName: ThemeName | null) => {
    const root = document.documentElement;
    const themeToApply = previewThemeName ? themes[previewThemeName] : themes[theme];
    for (const [key, value] of Object.entries(themeToApply)) {
        root.style.setProperty(key, value as string);
    }
  };

  const handleSettingsClose = () => {
    previewTheme(null); // Revert to saved theme on close
    setIsSettingsOpen(false);
  };

  const handleQuitGame = () => {
    quitAndResetToMenu();
    handleSettingsClose();
  };

  const handleResetStats = () => {
    setStats(initialStats);
  };

  /**
   * Depth-aware Minimax. 
   * Returns a higher score for faster wins and a lower score for delayed losses.
   */
  const minimax = useCallback((newBoard: SquareValue[], depth: number, isMaximizing: boolean): number => {
    const { winner: gameWinner } = calculateWinner(newBoard);
    if (gameWinner === aiPlayer) return 100 - depth;
    if (gameWinner === humanPlayer) return depth - 100;
    if (newBoard.every(square => square !== null)) return 0;

    const emptySquares = newBoard
      .map((val, index) => (val === null ? index : null))
      .filter((val): val is number => val !== null);

    if (isMaximizing) {
        let bestScore = -Infinity;
        for (const i of emptySquares) {
            const tempBoard = [...newBoard];
            tempBoard[i] = aiPlayer;
            const score = minimax(tempBoard, depth + 1, false);
            bestScore = Math.max(bestScore, score);
        }
        return bestScore;
    } else {
        let bestScore = Infinity;
        for (const i of emptySquares) {
            const tempBoard = [...newBoard];
            tempBoard[i] = humanPlayer;
            const score = minimax(tempBoard, depth + 1, true);
            bestScore = Math.min(bestScore, score);
        }
        return bestScore;
    }
  }, [calculateWinner]);

  const handleHintClick = useCallback(() => {
    const emptySquares = board
      .map((val, index) => (val === null ? index : null))
      .filter((val): val is number => val !== null);

    if (emptySquares.length === 0) return;

    let bestScore = Infinity;
    let bestMove = -1;

    for (const i of emptySquares) {
        const tempBoard = [...board];
        tempBoard[i] = humanPlayer;
        const score = minimax(tempBoard, 0, true);
        if (score < bestScore) {
            bestScore = score;
            bestMove = i;
        }
    }
    setSuggestedMove(bestMove === -1 ? emptySquares[0] : bestMove);
}, [board, minimax]);

  useEffect(() => {
    if (gameMode === 'pva' && currentPlayer === aiPlayer && !winner && aiDifficulty) {
      setIsAiTurn(true);
      if (!aiHasMoved) {
        setAiHasMoved(true);
      }

      const findAiMove = (squares: SquareValue[], difficulty: AIDifficulty): number => {
        const emptySquares = squares
          .map((val, index) => (val === null ? index : null))
          .filter((val): val is number => val !== null);

        if (emptySquares.length === 0) return -1;

        switch (difficulty) {
          case 'easy': {
            return emptySquares[Math.floor(Math.random() * emptySquares.length)];
          }
          case 'medium': {
            // 1. Can I win right now?
            for (const i of emptySquares) {
              const tempBoard = [...squares];
              tempBoard[i] = aiPlayer;
              if (calculateWinner(tempBoard).winner === aiPlayer) return i;
            }
            // 2. Do I need to block the human from winning?
            for (const i of emptySquares) {
              const tempBoard = [...squares];
              tempBoard[i] = humanPlayer;
              if (calculateWinner(tempBoard).winner === humanPlayer) return i;
            }
            // 3. Strategic fallback: Take center
            if (squares[4] === null) return 4;
            // 4. Strategic fallback: Take corners
            const corners = [0, 2, 6, 8].filter(i => squares[i] === null);
            if (corners.length > 0) return corners[Math.floor(Math.random() * corners.length)];
            // 5. Pure random
            return emptySquares[Math.floor(Math.random() * emptySquares.length)];
          }
          case 'hard': {
            // Perfect play with minimax
            if (emptySquares.length === 9) {
                const preferredStarts = [0, 2, 4, 6, 8]; // Corners or center
                return preferredStarts[Math.floor(Math.random() * preferredStarts.length)];
            }

            let bestScore = -Infinity;
            let bestMove = -1;

            for (const i of emptySquares) {
                const tempBoard = [...squares];
                tempBoard[i] = aiPlayer;
                const score = minimax(tempBoard, 0, false);
                if (score > bestScore) {
                    bestScore = score;
                    bestMove = i;
                }
            }
            return bestMove === -1 ? emptySquares[0] : bestMove;
          }
        }
      };

      // Faster AI response times
      const delay = aiDifficulty === 'hard' ? 100 : aiDifficulty === 'medium' ? 250 : 400;

      const timer = setTimeout(() => {
        const move = findAiMove(board, aiDifficulty);
        if (move !== -1) {
          handleSquareClick(move);
        }
        setIsAiTurn(false);
      }, delay);

      return () => clearTimeout(timer);
    }
  }, [gameMode, currentPlayer, winner, board, handleSquareClick, calculateWinner, aiDifficulty, aiHasMoved, minimax]);

  const startGame = useCallback((mode: GameMode, difficulty?: AIDifficulty) => {
    setIsViewFading(true);
    setTimeout(() => {
      setGameMode(mode);
      setAiDifficulty(difficulty || null);
      setBoard(Array(9).fill(null));
      setCurrentPlayer(startingPlayer);
      setWinner(null);
      setWinningLine(null);
      setIsAiTurn(false);
      setAiHasMoved(false);
      setStartingPlayer(prev => prev === 'X' ? 'O' : 'X');
      setIsViewFading(false);
    }, 300);
  }, [startingPlayer]);

  if (showSplashScreen) {
    return (
      <div className="min-h-screen bg-[--color-background] text-[--color-text-primary] flex flex-col items-center justify-center p-4 font-sans animate-fade-in">
        <div className="text-center">
          <h1 className="text-8xl font-bold tracking-tighter text-transparent bg-clip-text bg-gradient-to-r from-[var(--color-gradient-from)] to-[var(--color-gradient-to)] animate-pop-in">
            Tickey!
          </h1>
          <p className="text-[--color-text-secondary] mt-4 text-xl animate-fade-in" style={{ animationDelay: '0.4s' }}>
            With ❤️ By ARITRA
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[--color-background] text-[--color-text-primary] flex flex-col items-center justify-center p-4 font-sans relative overflow-hidden animate-fade-in">
      {(winner === 'X' || winner === 'O') && <Confetti winner={winner} />}
      <div className="absolute top-4 right-4 z-10 flex items-center gap-2">
        {gameMode === 'pva' && aiHasMoved && !winner && currentPlayer === humanPlayer && (
          <TipsButton onClick={handleHintClick} />
        )}
        <StatsButton onClick={() => setIsStatsModalOpen(true)} />
        <SettingsButton onClick={() => setIsSettingsOpen(true)} />
      </div>
       <SettingsModal
        isOpen={isSettingsOpen}
        onClose={handleSettingsClose}
        isSoundEnabled={isSoundEnabled}
        onSoundToggle={() => setIsSoundEnabled(prev => !prev)}
        volume={volume}
        onVolumeChange={(e) => setVolume(parseFloat(e.target.value))}
        theme={theme}
        onThemeChange={setTheme}
        onThemePreview={previewTheme}
        isHapticEnabled={isHapticEnabled}
        onHapticToggle={() => setIsHapticEnabled(prev => !prev)}
        gameMode={gameMode}
        onQuitGame={handleQuitGame}
        language={language}
        onLanguageChange={setLanguage}
        boardGridColor={boardGridColor}
        onBoardGridColorChange={setBoardGridColor}
        boardGap={boardGap}
        onBoardGapChange={setBoardGap}
      />
      <StatsModal
        isOpen={isStatsModalOpen}
        onClose={() => setIsStatsModalOpen(false)}
        stats={stats}
        onResetStats={handleResetStats}
        language={language}
      />

      <header className="mb-8 text-center">
        <h1 className="text-6xl font-bold tracking-tighter text-transparent bg-clip-text bg-gradient-to-r from-[var(--color-gradient-from)] to-[var(--color-gradient-to)]">
          Tickey!
        </h1>
        <p className="text-[--color-text-secondary] mt-2">{t('subtitle', language)}</p>
      </header>

      <main className="flex flex-col items-center">
        {gameMode ? (
          <div className={`flex flex-col items-center ${isViewFading ? 'animate-fade-out' : 'animate-fade-in'}`}>
            <GameInfo winner={winner} currentPlayer={currentPlayer} gameMode={gameMode} isAiTurn={isAiTurn} stats={stats} language={language} />
            <Board squares={board} onSquareClick={handleSquareClick} winner={winner} isLocked={isAiTurn} winningLine={winningLine} suggestedMove={suggestedMove} isDraw={winner === 'Draw'} currentPlayer={currentPlayer} />
            <ResetButton onReset={restartGame} onQuit={quitAndResetToMenu} winner={winner} language={language} />
          </div>
        ) : (
          <div className={isViewFading ? 'animate-fade-out' : 'animate-fade-in'}>
            <GameModeSelector onSelectMode={startGame} isSoundEnabled={isSoundEnabled} onSoundToggle={() => setIsSoundEnabled(prev => !prev)} language={language} />
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useCallback, useEffect, useRef } from 'react';
import Board from './components/Board.tsx';
import GameInfo from './components/GameInfo.tsx';
import ResetButton from './components/ResetButton.tsx';
import GameModeSelector from './components/GameModeSelector.tsx';
import SettingsButton from './components/SettingsButton.tsx';
import SettingsModal from './components/SettingsModal.tsx';
import StatsButton from './components/StatsButton.tsx';
import StatsModal from './components/StatsModal.tsx';
import TipsButton from './components/TipsButton.tsx';
import Confetti from './components/Confetti.tsx';
import { t } from './utils/translations.ts';
import type { SquareValue, Player, GameMode, AIDifficulty, ThemeName, GameStats, Language } from './types.ts';

// --- Constants ---
const humanPlayer: Player = 'X';
const aiPlayer: Player = 'O';

const initialStats: GameStats = {
  totalGames: 0,
  xWins: 0,
  oWins: 0,
  draws: 0,
  xStreak: 0,
  oStreak: 0,
};

const themes: Record<ThemeName, Record<string, string>> = {
  classic: {
