import React, { useState } from 'react';
import type { SquareValue, Player } from '../types.ts';

interface SquareProps {
  value: SquareValue;
  onClick: () => void;
  isLocked?: boolean;
  isWinning?: boolean;
  isSuggested?: boolean;
  isDraw?: boolean;
  currentPlayer: Player;
}

const Square: React.FC<SquareProps> = ({ value, onClick, isLocked, isWinning, isSuggested, isDraw, currentPlayer }) => {
  const [isPressed, setIsPressed] = useState(false);

  const handlePointerDown = (e: React.PointerEvent) => {
    if (!!value || isLocked) return;
    setIsPressed(true);
    // Instant trigger on pointer down for better responsiveness
    onClick();
  };

  const handlePointerUp = () => setIsPressed(false);
  const handlePointerLeave = () => setIsPressed(false);

  const textClass = value === 'X' 
    ? 'text-[--color-player-x]' 
    : 'text-[--color-player-o]';

  const winningClass = isWinning
    ? 'animate-win z-10'
    : 'bg-[--color-square-bg] hover:bg-[--color-square-hover]';

  const suggestedClass = isSuggested && !value ? 'animate-suggest' : '';
  const drawClass = isDraw && value ? 'animate-head-shake' : '';

  return (
    <button
      onPointerDown={handlePointerDown}
      onPointerUp={handlePointerUp}
      onPointerLeave={handlePointerLeave}
      className={`relative w-[72px] h-[72px] xs:w-24 xs:h-24 md:w-28 md:h-28 rounded-xl flex items-center justify-center text-4xl xs:text-5xl md:text-6xl font-black transition-all duration-75 select-none touch-none focus:outline-none focus:ring-4 focus:ring-[--color-accent] disabled:cursor-not-allowed ${winningClass} ${suggestedClass} ${isPressed ? 'scale-90 brightness-125' : 'scale-100'} ${value ? 'animate-jelly' : ''}`}
      disabled={!!value || isLocked}
      aria-label={`Square ${isSuggested ? 'suggested move' : ''}`}
    >
      <span className={`${value ? 'animate-pop-in' : 'opacity-0'} ${textClass} ${drawClass} pointer-events-none drop-shadow-lg`}>
        {value}
      </span>
      {/* Dynamic tap ring */}
      {isPressed && !value && !isLocked && (
        <div className="absolute inset-0 rounded-xl border-4 border-[--color-accent] animate-ping opacity-30" />
      )}
    </button>
  );
