  squares: SquareValue[];
  onSquareClick: (index: number) => void;
  winner: Player | 'Draw' | null;
  isLocked?: boolean;
  winningLine: number[] | null;
  suggestedMove?: number | null;
  isDraw?: boolean;
  currentPlayer: Player;
  boardTheme: BoardTheme;
}

