  isOpen,
  onClose,
  isSoundEnabled,
  onSoundToggle,
  volume,
  onVolumeChange,
  theme,
  onThemeChange,
  boardTheme,
  onBoardThemeChange,
  onThemePreview,
  isHapticEnabled,
  onHapticToggle,
  gameMode,
  onQuitGame,
  language,
  onLanguageChange,
  boardGridColor,
  onBoardGridColorChange,
  boardGap,
  onBoardGapChange,
}) => {
  const [showQuitConfirmation, setShowQuitConfirmation] = useState(false);
  const [isLanguageSelectorOpen, setIsLanguageSelectorOpen] = useState(false);

  useEffect(() => {
    if (isOpen) {
      setShowQuitConfirmation(false);
