import type { SquareValue, Player, GameMode, AIDifficulty, ThemeName, BoardTheme, GameStats, Language } from './types.ts';

// --- Constants ---
const humanPlayer: Player = 'X';
const aiPlayer: Player = 'O';

const initialStats: GameStats = {
  totalGames: 0,
  xWins: 0,
  oWins: 0,
  draws: 0,
  xStreak: 0,
  oStreak: 0,
