    '--color-text-primary': '#dce2d9',
    '--color-text-secondary': '#9eac9b',
    '--color-player-x': '#84cc16',
    '--color-player-o': '#f59e0b',
    '--color-accent': '#10b981',
    '--color-accent-hover': '#059669',
    '--color-board-bg': '#223c33',
    '--color-square-bg': '#1a2e27',
    '--color-square-hover': '#2f4d40',
